SELECT ?z ?label ?point WHERE {
  ?z rdfs:label ?label .
  ?point brick:isPointOf ?z .
  ?point rdf:type brick:Occupancy .
}

SELECT ?point ?ref ?sid WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> .
  ?point rdf:type brick:Occupancy .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?sid .
}

SELECT ?point ?sid WHERE {
  ?point rdf:type brick:Occupancy .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?sid .
} LIMIT 50

SELECT ?point ?sid WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?sid .
  FILTER (CONTAINS(STR(?point), "Occupanc"))
} LIMIT 60

SELECT ?point ?sid WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?sid .
  FILTER (CONTAINS(STR(?point), "Zone_F3") && CONTAINS(STR(?point), "Occupanc"))
}

